const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let d;
try { d = JSON.parse(raw); } catch (e) { d = { nota: 0, resumo: 'Não foi possível interpretar a resposta da IA.' }; }
const text = $('Extrair texto do PDF').first().json.text || '';
if (!d.email) { const m = text.match(/[\w.+-]+@[\w-]+\.[\w.-]+/); if (m) d.email = m[0]; }
return [{ json: d }];
